#include "profiles.hpp"
#include "core/binary.hpp"
#include "core/unicode.hpp"
#include <windows.h>
#include <charconv>
#include <set>
#include <fstream>
namespace crackhood {
static bool ipv4(const std::string&s){size_t pos=0;for(unsigned i=0;i<4;++i){auto end=s.find('.',pos);if(i==3){if(end!=std::string::npos)return false;end=s.size();}else if(end==std::string::npos)return false;if(end==pos)return false;unsigned value=256;auto r=std::from_chars(s.data()+pos,s.data()+end,value);if(r.ec!=std::errc{}||r.ptr!=s.data()+end||value>255)return false;pos=end+1;}return true;}
static void validate(const std::vector<Profile>&rows){if(rows.size()>64)throw std::runtime_error("Invalid number of console profiles");std::set<std::string>ids;unsigned defaults=0;for(auto&p:rows){if(p.id.value.empty()||p.id.value.size()>64||!ids.insert(p.id.value).second||p.id.value.find_first_not_of("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_")!=std::string::npos||p.name.empty()||p.name.size()>256||!ipv4(p.address))throw std::runtime_error("Invalid console name or IPv4 address");utf16(p.name);for(unsigned char c:p.name)if(c<32||c=='\\'||c=='/')throw std::runtime_error("Invalid console name");defaults+=p.is_default;}if(defaults!=(rows.empty()?0u:1u))throw std::runtime_error("Exactly one default console is required");}
Result<std::vector<Profile>> decode_profiles(std::span<const std::byte>b){try{if(b.size()>65536)throw std::runtime_error("Profiles are too large");Reader r{b};if(r.number(4)!=0x50484b43||r.number(4)!=1)throw std::runtime_error("Profile format is corrupted");auto count=r.number(4);if(count>64)throw std::runtime_error("Too many profiles");std::vector<Profile>rows;while(count--){Profile p;p.id.value=r.text();p.name=r.text();p.address=r.text();auto def=r.number(1);if(def>1)throw std::runtime_error("Invalid default profile");p.is_default=def!=0;rows.push_back(std::move(p));}if(r.offset!=b.size())throw std::runtime_error("Invalid additional profile data");validate(rows);return rows;}catch(const std::exception&e){return Error{ErrorCode::Protocol,e.what()};}}
Result<std::vector<std::byte>> encode_profiles(const std::vector<Profile>&rows){try{validate(rows);Writer w;w.number(0x50484b43,4);w.number(1,4);w.number(rows.size(),4);for(auto&p:rows){w.text(p.id.value);w.text(p.name);w.text(p.address);w.number(p.is_default,1);}return w.bytes;}catch(const std::exception&e){return Error{ErrorCode::InvalidName,e.what()};}}
std::filesystem::path user_root(){wchar_t path[32768]{};if(!GetEnvironmentVariableW(L"LOCALAPPDATA",path,32768))throw std::runtime_error("LocalAppData is unavailable");return std::filesystem::path(path)/L"Crackhood";}
Result<std::vector<Profile>> load_profiles(){try{auto path=user_root()/L"profiles.bin";if(!std::filesystem::exists(path))return std::vector<Profile>{{{"rgh"},"Xbox 360","10.10.10.218",true}};auto size=std::filesystem::file_size(path);if(size>65536)return Error{ErrorCode::Protocol,"Profiles are too large"};std::vector<std::byte>b(static_cast<size_t>(size));std::ifstream f(path,std::ios::binary);f.read(reinterpret_cast<char*>(b.data()),b.size());if(!f)return Error{ErrorCode::AccessDenied,"Could not read profiles"};auto result=decode_profiles(b);if(std::holds_alternative<Error>(result)){std::error_code ec;std::filesystem::copy_file(path,user_root()/(L"profiles.corrupt-"+std::to_wstring(GetTickCount64())+L".bin"),ec);}return result;}catch(const std::exception&e){return Error{ErrorCode::AccessDenied,e.what()};}}
Result<Unit> save_profiles(const std::vector<Profile>&rows){auto result=encode_profiles(rows);auto bytes=std::get_if<std::vector<std::byte>>(&result);if(!bytes)return std::get<Error>(result);try{auto root=user_root();std::filesystem::create_directories(root);auto temp=root/(L"profiles-"+std::to_wstring(GetCurrentProcessId())+L".tmp");{std::ofstream f(temp,std::ios::binary|std::ios::trunc);f.write(reinterpret_cast<const char*>(bytes->data()),bytes->size());f.flush();if(!f)return Error{ErrorCode::DiskFull,"Could not save profiles"};}if(!MoveFileExW(temp.c_str(),(root/L"profiles.bin").c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH))return Error{ErrorCode::AccessDenied,"Could not replace profiles"};return Unit{};}catch(const std::exception&e){return Error{ErrorCode::AccessDenied,e.what()};}}
}
